package com.bidx.servlet;import jakarta.servlet.http.*;import jakarta.servlet.*;import java.io.*;import com.bidx.service.*;import com.bidx.model.*;
class LoginServlet extends BaseServlet {private final AuthService s=new AuthService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{view(r,p,"auth/login");}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{try{User u=s.login(r.getParameter("login"),r.getParameter("password"));r.getSession().invalidate();HttpSession x=r.getSession(true);x.setAttribute("user",u);flash(r,"Welcome back, "+u.name+".","success");p.sendRedirect(r.getContextPath()+"/dashboard");}catch(IllegalArgumentException e){flash(r,e.getMessage(),"danger");p.sendRedirect(r.getContextPath()+"/login");}}}
class RegisterServlet extends BaseServlet {private final AuthService s=new AuthService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{view(r,p,"auth/register");}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{try{if(!java.util.Objects.equals(r.getParameter("password"),r.getParameter("confirmPassword")))throw new IllegalArgumentException("Passwords do not match.");s.register(r.getParameter("name"),r.getParameter("username"),r.getParameter("email"),r.getParameter("phone"),r.getParameter("password"),r.getParameter("accountType"));flash(r,"Your account is ready. Please sign in.","success");p.sendRedirect(r.getContextPath()+"/login");}catch(IllegalArgumentException e){flash(r,e.getMessage(),"danger");p.sendRedirect(r.getContextPath()+"/register");}}}
class LogoutServlet extends BaseServlet {protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{r.getSession().invalidate();p.sendRedirect(r.getContextPath()+"/");}}
